INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, published_at) VALUES ('2.66.1', 2066001, 'windows', 'releases/CosmicPlatformer-Setup-2.66.1.exe', 'CosmicPlatformer-Setup-2.66.1.exe', 122329777, '4315c97cf6ab21281682969ffbe584eec8d1d525df33be6c5075ab9b1e305c3b', 'Version 2.66.1 :
• Asterion en vrai pixel art : dans CLANS › RAIDS et la fiche d''un événement, le titan est désormais un sprite détaillé, partie par partie (crâne Skullmaw, bras Dreadfang et Pyroclast, torse Heartbreaker, abdomen Voidworm, jambes Graviton et Titanus, cœur cosmique, aura) qui respire, dont le cœur bat et autour duquel dérivent des particules. Survolez une partie à la souris ou allez-y au clavier ou à la manette : elle s''éclaire et son infobulle donne son nom, son gigaboss, son état (sous attaque, affaiblie, détruite ou non découverte) et l''effet de sa destruction sur Asterion.

Version 2.66.0 :
• Raids de clan, phase 2 : la branche « BRAS DROIT » d''Asterion se joue. Pendant un raid en cours, la fiche de l''événement ouvre la carte de la branche : huit zones reliées sur le bras du titan (l''Épaule et ses trois points d''apparition, le Biceps de basalte aux plateformes qui respirent, la Veine de magma et sa coulée, le Coude-forge et ses deux soufflets à détruire par deux groupes, la Grotte des scories secrète, l''Avant-bras et son raccourci, le Poignet-verrou ouvert par deux générateurs, la Main de Pyroclast scellée jusqu''à la prochaine version), leur état, les objectifs faits et par quel groupe, les groupes et où ils sont, « Rejoindre » ou « Aider » un autre groupe.
• Combat en instances de 8 joueurs : chaque groupe joue en verrouillage par entrées comme la coopération (arrivée en cours de partie, 60 s pour revenir après une déconnexion, puis la place est libérée), passe de zone en zone sans perdre ses cœurs ni ses pouvoirs, avec une minimap, le panneau du groupe, les objectifs de la zone, les alertes de la branche et l''annonce des coulées de magma. Le serveur ne valide un objectif que si la majorité des joueurs de l''instance a vu exactement la même chose ; un objectif détruit par deux groupes en même temps ne compte qu''une fois.', '2026-11-17T23:13:36.033Z') ON CONFLICT (version) DO NOTHING;
